import java.util.*;
final class DnsApp {
    record Name(String text, int end) {}
    static Name name(int[] b, int start) {
        List<String> labels = new ArrayList<>();
        int position = start, end = -1, pointers = 0;
        while (true) {
            int value = (int)LinkNetwork.integer(b, position, 1);
            if (value == 0) {
                if (end < 0)
                    end = position + 1;
                break;
            }
            if (value >= 192) {
                int low = (int)LinkNetwork.integer(b, position + 1, 1);
                if (end < 0)
                    end = position + 2;
                if (++pointers > 16)
                    throw new LinkNetwork.Bad("dns: compression loop");
                position = (value - 192) * 256 + low;
                if (position >= b.length)
                    throw new LinkNetwork.Bad("dns: pointer out of range");
            } else if (value >= 64)
                throw new LinkNetwork.Bad("dns: bad label type");
            else {
                StringBuilder label = new StringBuilder();
                for (int i = 0; i < value; i++) {
                    int c = (int)LinkNetwork.integer(b, position + 1 + i, 1);
                    if (c >= 33 && c <= 126 && c != 46 && c != 92)
                        label.append((char)c);
                    else
                        label.append(String.format(Locale.ROOT, "\\%03d", c));
                }
                labels.add(label.toString());
                position += value + 1;
            }
        }
        return new Name(labels.isEmpty() ? "<root>" : String.join(".", labels), end);
    }
    static String type(long value) {
        return switch ((int)value) {
            case 1 -> "A";
            case 2 -> "NS";
            case 5 -> "CNAME";
            case 6 -> "SOA";
            case 12 -> "PTR";
            case 15 -> "MX";
            case 16 -> "TXT";
            case 28 -> "AAAA";
            default -> "TYPE" + value;
        };
    }
    static String rcode(long value) {
        String[] names = {"NoError", "FormErr", "ServFail", "NXDomain", "NotImp", "Refused"};
        return value < names.length ? names[(int)value] : "RCODE" + value;
    }
    static String ipv6(int[] b, int start) {
        List<String> groups = new ArrayList<>();
        int best = -1, length = 1;
        for (int i = 0; i < 8; i++)
            groups.add(Integer.toHexString(LinkNetwork.word(b, start + 2 * i)));
        for (int i = 0; i < 8; i++)
            if (groups.get(i).equals("0")) {
                int end = i;
                while (end < 8 && groups.get(end).equals("0"))
                    end++;
                if (end - i > length) {
                    best = i;
                    length = end - i;
                }
                i = end - 1;
            }
        if (best < 0)
            return String.join(":", groups);
        return String.join(":", groups.subList(0, best)) +
            "::" + String.join(":", groups.subList(best + length, 8));
    }
    static int[] dissect(Main.Packet p, int[] b) {
        LinkNetwork.integer(b, 11, 1);
        int flags = LinkNetwork.word(b, 2);
        p.put("dns.id", LinkNetwork.word(b, 0));
        p.put("dns.flags", flags);
        p.put("dns.flags.response", (flags >> 15) & 1);
        p.put("dns.flags.opcode", (flags >> 11) & 15);
        p.put("dns.flags.rcode", flags & 15);
        String[] counts = {"queries", "answers", "auth_rr", "add_rr"};
        for (int i = 0; i < 4; i++)
            p.put("dns.count." + counts[i], LinkNetwork.word(b, 4 + 2 * i));
        int position = 12;
        for (int i = 0; i < p.num("dns.count.queries"); i++) {
            Name n = name(b, position);
            LinkNetwork.integer(b, n.end, 4);
            p.append("dns.qry.name", n.text);
            p.append("dns.qry.type", LinkNetwork.word(b, n.end));
            position = n.end + 4;
        }
        String[] recordFields = {"dns.answer", "dns.authority", "dns.additional"};
        for (int group = 0; group < 3; group++)
            for (int i = 0; i < p.num("dns.count." + counts[group + 1]); i++) {
                Name n = name(b, position);
                position = n.end;
                LinkNetwork.integer(b, position + 9, 1);
                int kind = LinkNetwork.word(b, position), cls = LinkNetwork.word(b, position + 2),
                    size = LinkNetwork.word(b, position + 8);
                long ttl = LinkNetwork.integer(b, position + 4, 4);
                int start = position + 10, end = start + size, read = end;
                if (end > b.length)
                    throw new LinkNetwork.Bad("dns: truncated");
                String data;
                if (kind == 1) {
                    data = LinkNetwork.ipv4(LinkNetwork.integer(b, start, 4));
                    read = start + 4;
                } else if (kind == 28) {
                    data = ipv6(b, start);
                    read = start + 16;
                } else if (kind == 2 || kind == 5 || kind == 12) {
                    Name target = name(b, start);
                    data = target.text;
                    read = target.end;
                } else if (kind == 15) {
                    int preference = LinkNetwork.word(b, start);
                    Name target = name(b, start + 2);
                    data = preference + " " + target.text;
                    read = target.end;
                } else if (kind == 6) {
                    Name first = name(b, start), second = name(b, first.end);
                    read = second.end;
                    StringBuilder text = new StringBuilder(first.text + " " + second.text);
                    for (int j = 0; j < 5; j++) {
                        text.append(" ").append(LinkNetwork.integer(b, read, 4));
                        read += 4;
                    }
                    data = text.toString();
                } else
                    data = size + " bytes";
                if (read != end)
                    throw new LinkNetwork.Bad("dns: bad rdata length");
                p.append(recordFields[group], n.text + " " + type(kind) + " " +
                                                  (cls == 1 ? "IN" : "CLASS" + cls) + " " + ttl + " " + data);
                if (group == 0 && kind == 1)
                    p.append("dns.a", LinkNetwork.integer(b, start, 4));
                if (group == 0)
                    p.answers.add(type(kind) + " " + data);
                position = end;
            }
        return new int[0];
    }
}

import java.util.*;
final class Flows {
    static final String[] MARKS = {"retransmission", "out_of_order", "lost_segment", "duplicate_ack"};
    record Endpoint(long address, long port) {
        public String toString() {
            return LinkNetwork.ipv4(address) + (port < 0 ? "" : ":" + port);
        }
    }
    static final class Previous {
        long ack, window;
        int number, count;
        Previous(long ack, long window, int number) {
            this.ack = ack;
            this.window = window;
            this.number = number;
        }
    }
    static final class Side {
        String name;
        long isn = -1, mss = -1, ws = -1, base = -1, expected = -1, advanced, packets, payload;
        Set<String> intervals = new HashSet<>();
        Previous previous;
        long[] marks = new long[4];
        Side(String name) {
            this.name = name;
        }
    }
    static final class Stream {
        int number, syn = -1, synAck = -1, ack = -1;
        Endpoint client, server;
        String state;
        Side clientSide = new Side("client"), serverSide = new Side("server"), closer;
        long start, end, packets, bytes, finalAck;
        List<String> history = new ArrayList<>(), events = new ArrayList<>();
        Stream(int number, Endpoint client, Endpoint server, String state, Main.Packet p) {
            this.number = number;
            this.client = client;
            this.server = server;
            this.state = state;
            start = p.time;
            change(state, p.number);
        }
        void change(String state, int number) {
            this.state = state;
            history.add(state + " " + number);
        }
        void record(Side side, Main.Packet p) {
            side.isn = p.num("tcp.seq_raw");
            side.mss = p.has("tcp.options.mss") ? p.num("tcp.options.mss") : -1;
            side.ws = p.has("tcp.options.wscale") ? p.num("tcp.options.wscale") : -1;
            if (side == clientSide)
                syn = p.number;
            else
                synAck = p.number;
        }
    }
    final List<Stream> streams = new ArrayList<>();
    void track(Main.Packet p) {
        Endpoint source = new Endpoint(p.num("ip.src"), p.num("tcp.srcport")),
                 destination = new Endpoint(p.num("ip.dst"), p.num("tcp.dstport"));
        boolean syn = p.num("tcp.flags.syn") == 1, ackSet = p.num("tcp.flags.ack") == 1,
                fin = p.num("tcp.flags.fin") == 1, rst = p.num("tcp.flags.rst") == 1;
        long seq = p.num("tcp.seq_raw"), ack = ackSet ? p.num("tcp.ack_raw") : 0;
        Stream stream = null;
        for (int i = streams.size() - 1; i >= 0; i--) {
            Stream candidate = streams.get(i);
            if ((candidate.client.equals(source) && candidate.server.equals(destination)) ||
                (candidate.client.equals(destination) && candidate.server.equals(source))) {
                stream = candidate;
                break;
            }
        }
        if (stream == null ||
            ((stream.state.equals("CLOSED") || stream.state.equals("RESET")) && syn && !ackSet)) {
            stream = new Stream(streams.size(), syn && ackSet ? destination : source,
                                syn && ackSet ? source : destination,
                                syn ? (ackSet ? "SYN_RECEIVED" : "SYN_SENT") : "ESTABLISHED", p);
            if (syn)
                stream.record(ackSet ? stream.serverSide : stream.clientSide, p);
            streams.add(stream);
        }
        p.put("tcp.stream", stream.number);
        Side side = source.equals(stream.client) ? stream.clientSide : stream.serverSide,
             other = side == stream.clientSide ? stream.serverSide : stream.clientSide;
        if (side.base < 0)
            side.base = seq;
        if (ackSet && other.base < 0)
            other.base = ack;
        long relative = (seq - side.base + 4294967296L) % 4294967296L;
        p.put("tcp.seq", relative);
        if (ackSet)
            p.put("tcp.ack", (ack - other.base + 4294967296L) % 4294967296L);
        long size = p.num("tcp.len") + (syn ? 1 : 0) + (fin ? 1 : 0);
        int mark = -1;
        if (size >= 1) {
            if (side.expected >= 0 && relative != side.expected) {
                if (relative > side.expected)
                    mark = 2;
                else if (side.intervals.contains(relative + ":" + size))
                    mark = 0;
                else
                    mark = p.time - side.advanced < 3000 ? 1 : 0;
            }
            side.intervals.add(relative + ":" + size);
            if (side.expected < 0 || relative + size > side.expected) {
                side.expected = relative + size;
                side.advanced = p.time;
            }
        } else if (ackSet && !rst && side.previous != null && ack == side.previous.ack &&
                   p.num("tcp.window") == side.previous.window) {
            mark = 3;
            side.previous.count++;
            p.duplicate = "[TCP Dup ACK " + side.previous.number + "#" + side.previous.count + "] ";
        }
        if (ackSet && mark != 3)
            side.previous = new Previous(ack, p.num("tcp.window"), p.number);
        if (mark >= 0) {
            p.put("tcp.analysis." + MARKS[mark], 0);
            side.marks[mark]++;
            stream.events.add("event " + p.number + " " + side.name + " " + MARKS[mark] + " seq " + relative +
                              " len " + size);
        }
        p.put("tcp.window.calc",
              p.num("tcp.window") *
                  (stream.clientSide.ws >= 0 && stream.serverSide.ws >= 0 && !syn ? 1L << (int)side.ws : 1));
        if (rst) {
            if (!stream.state.equals("CLOSED") && !stream.state.equals("RESET"))
                stream.change("RESET", p.number);
        } else if (stream.state.equals("SYN_SENT") && side == stream.serverSide && syn && ackSet &&
                   ack == (stream.clientSide.isn + 1) % 4294967296L) {
            stream.change("SYN_RECEIVED", p.number);
            stream.record(side, p);
        } else if (stream.state.equals("SYN_RECEIVED") && side == stream.clientSide && ackSet && !syn &&
                   ack == (stream.serverSide.isn + 1) % 4294967296L) {
            stream.change("ESTABLISHED", p.number);
            stream.ack = p.number;
        } else if (stream.state.equals("ESTABLISHED") && fin) {
            stream.change("FIN_WAIT", p.number);
            stream.closer = side;
        } else if (stream.state.equals("FIN_WAIT") && fin && side != stream.closer) {
            stream.change("CLOSING", p.number);
            stream.finalAck = (seq + p.num("tcp.len") + 1) % 4294967296L;
        } else if (stream.state.equals("CLOSING") && side == stream.closer && ackSet &&
                   ack == stream.finalAck)
            stream.change("CLOSED", p.number);
        side.packets++;
        side.payload += p.num("tcp.len");
        stream.packets++;
        stream.bytes += p.length;
        stream.end = p.time;
    }
    static final class Conversation {
        String kind;
        Endpoint a, b;
        int first;
        long start, end;
        long[] packets = new long[2], bytes = new long[2];
        Conversation(String kind, Endpoint a, Endpoint b, Main.Packet p) {
            this.kind = kind;
            this.a = a;
            this.b = b;
            first = p.number;
            start = p.time;
        }
        long totalBytes() {
            return bytes[0] + bytes[1];
        }
        long totalPackets() {
            return packets[0] + packets[1];
        }
    }
    static List<String> conversations(List<Main.Packet> packets) {
        Map<String, Conversation> grouped = new HashMap<>();
        for (Main.Packet p : packets)
            for (String kind : List.of("ipv4", "tcp", "udp")) {
                if (!p.has(kind.equals("ipv4")  ? "ip.src"
                           : kind.equals("tcp") ? "tcp.stream"
                                                : "udp.srcport"))
                    continue;
                Endpoint source = new Endpoint(p.num("ip.src"),
                                               kind.equals("ipv4") ? -1 : p.num(kind + ".srcport")),
                         destination = new Endpoint(p.num("ip.dst"),
                                                    kind.equals("ipv4") ? -1 : p.num(kind + ".dstport"));
                String first = source.toString(), second = destination.toString();
                String key = kind + ":" +
                             (kind.equals("tcp")            ? p.num("tcp.stream")
                              : first.compareTo(second) < 0 ? first + ":" + second
                                                            : second + ":" + first);
                Conversation c = grouped.get(key);
                if (c == null) {
                    c = new Conversation(kind, source, destination, p);
                    grouped.put(key, c);
                }
                int direction = source.equals(c.a) ? 0 : 1;
                c.packets[direction]++;
                c.bytes[direction] += p.length;
                c.end = p.time;
            }
        List<Conversation> ordered = new ArrayList<>(grouped.values());
        ordered.sort(Comparator.comparingLong(Conversation::totalBytes)
                         .reversed()
                         .thenComparing(Comparator.comparingLong(Conversation::totalPackets).reversed())
                         .thenComparingInt(c -> List.of("ipv4", "tcp", "udp").indexOf(c.kind))
                         .thenComparingInt(c -> c.first));
        List<String> output = new ArrayList<>();
        output.add(
            "type,endpoint_a,endpoint_b,packets,bytes,packets_a_to_b,bytes_a_to_b,packets_b_to_a,bytes_b_to_a,start,duration");
        long origin = packets.getFirst().time;
        for (Conversation c : ordered)
            output.add(c.kind + "," + c.a + "," + c.b + "," + c.totalPackets() + "," + c.totalBytes() + "," +
                       c.packets[0] + "," + c.bytes[0] + "," + c.packets[1] + "," + c.bytes[1] + "," +
                       Main.seconds(c.start - origin) + "," + Main.seconds(c.end - c.start));
        return output;
    }
    static List<String> endpoints(List<Main.Packet> packets) {
        Map<Long, long[]> counts = new HashMap<>();
        for (Main.Packet p : packets)
            if (p.has("ip.src"))
                for (int side = 0; side < 2; side++) {
                    long address = p.num(side == 0 ? "ip.src" : "ip.dst");
                    long[] row = counts.computeIfAbsent(address, key -> new long[4]);
                    row[side * 2]++;
                    row[side * 2 + 1] += p.length;
                }
        List<Long> ordered = new ArrayList<>(counts.keySet());
        ordered.sort((a, b) -> {
            long[] x = counts.get(a), y = counts.get(b);
            int c = Long.compare(y[1] + y[3], x[1] + x[3]);
            if (c == 0)
                c = Long.compare(y[0] + y[2], x[0] + x[2]);
            return c != 0 ? c : Long.compare(a, b);
        });
        List<String> output = new ArrayList<>();
        output.add("address,packets,bytes,tx_packets,tx_bytes,rx_packets,rx_bytes");
        for (long address : ordered) {
            long[] row = counts.get(address);
            output.add(LinkNetwork.ipv4(address) + "," + (row[0] + row[2]) + "," + (row[1] + row[3]) + "," +
                       row[0] + "," + row[1] + "," + row[2] + "," + row[3]);
        }
        return output;
    }
}

import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.io.IOException;
import java.util.*;
final class Hexdump {
    static List<Main.Packet> read() throws IOException {
        List<String> lines = Files.readAllLines(Path.of("input/capture.txt"), StandardCharsets.US_ASCII);
        List<Main.Packet> packets = new ArrayList<>();
        Main.Packet packet = null;
        List<Integer> bytes = new ArrayList<>();
        for (int line = 0; line <= lines.size(); line++) {
            String text = line < lines.size() ? lines.get(line) : "PACKET ";
            if (text.startsWith("PACKET ")) {
                if (packet != null) {
                    if (packet.reason == null && bytes.size() != packet.length)
                        packet.reason =
                            "dump: length mismatch (header " + packet.length + ", data " + bytes.size() + ")";
                    packet.bytes = bytes.stream().mapToInt(Integer::intValue).toArray();
                    packets.add(packet);
                }
                if (line == lines.size())
                    break;
                String[] parts = text.split(" ");
                packet = new Main.Packet(Integer.parseInt(parts[1]), Long.parseLong(parts[2]),
                                         Integer.parseInt(parts[3]));
                bytes = new ArrayList<>();
            } else if (!text.isEmpty() && packet.reason == null) {
                if (!text.matches("[0-9a-f]{4}  [0-9a-f]{2}( [0-9a-f]{2}){0,15}"))
                    packet.reason = "dump: bad line " + (line + 1);
                else if (Integer.parseInt(text.substring(0, 4), 16) != bytes.size())
                    packet.reason = "dump: offset mismatch at line " + (line + 1);
                else
                    for (String value : text.substring(6).split(" "))
                        bytes.add(Integer.parseInt(value, 16));
            }
        }
        return packets;
    }
    static List<String> lines(int[] bytes) {
        List<String> output = new ArrayList<>();
        for (int start = 0; start < bytes.length; start += 16) {
            List<String> hex = new ArrayList<>();
            StringBuilder text = new StringBuilder();
            for (int i = start; i < Math.min(start + 16, bytes.length); i++) {
                hex.add(String.format(Locale.ROOT, "%02x", bytes[i]));
                text.append(bytes[i] >= 32 && bytes[i] <= 126 ? (char)bytes[i] : '.');
            }
            output.add(String.format(Locale.ROOT, "%04x  %-47s  |%s|", start, String.join(" ", hex), text));
        }
        return output;
    }
}

import java.util.*;
final class LinkNetwork {
    static final class Bad extends RuntimeException {
        Bad(String reason) {
            super(reason);
        }
    }
    static long integer(int[] bytes, int position, int count) {
        if (position < 0 || position + count > bytes.length)
            throw new Bad("dns: truncated");
        long value = 0;
        for (int i = 0; i < count; i++)
            value = value * 256 + bytes[position + i];
        return value;
    }
    static int word(int[] bytes, int position) {
        return (int)integer(bytes, position, 2);
    }
    static int[] slice(int[] bytes, int start, int end) {
        return Arrays.copyOfRange(bytes, start, end);
    }
    static String checksum(int[] bytes) {
        long sum = 0;
        for (int i = 0; i < bytes.length; i += 2)
            sum += bytes[i] * 256 + (i + 1 < bytes.length ? bytes[i + 1] : 0);
        while (sum > 65535)
            sum = (sum & 65535) + (sum >> 16);
        return sum == 65535 ? "good" : "bad";
    }
    static String ipv4(long value) {
        return ((value >> 24) & 255) + "." + ((value >> 16) & 255) + "." + ((value >> 8) & 255) + "." +
            (value & 255);
    }
    static String mac(long value) {
        List<String> parts = new ArrayList<>();
        for (int shift = 40; shift >= 0; shift -= 8)
            parts.add(String.format(Locale.ROOT, "%02x", (value >> shift) & 255));
        return String.join(":", parts);
    }
    static int[] ethernet(Main.Packet p, int[] b) {
        if (b.length < 14)
            throw new Bad("eth: truncated");
        p.put("eth.dst", integer(b, 0, 6));
        p.put("eth.src", integer(b, 6, 6));
        p.put("eth.type", word(b, 12));
        return slice(b, 14, b.length);
    }
    static int[] arp(Main.Packet p, int[] b) {
        if (b.length < 28)
            throw new Bad("arp: truncated");
        if (word(b, 0) != 1 || word(b, 2) != 2048 || b[4] != 6 || b[5] != 4)
            throw new Bad("arp: unsupported format");
        p.put("arp.opcode", word(b, 6));
        p.put("arp.src.hw", integer(b, 8, 6));
        p.put("arp.src.ip", integer(b, 14, 4));
        p.put("arp.dst.hw", integer(b, 18, 6));
        p.put("arp.dst.ip", integer(b, 24, 4));
        return new int[0];
    }
    static int[] ipv4(Main.Packet p, int[] b) {
        if (b.length < 20)
            throw new Bad("ip: truncated header");
        int version = b[0] / 16, h = b[0] % 16 * 4;
        if (version != 4)
            throw new Bad("ip: bad version " + version);
        if (h < 20)
            throw new Bad("ip: bad header length " + h);
        if (b.length < h)
            throw new Bad("ip: truncated header");
        int total = word(b, 2);
        if (total < h)
            throw new Bad("ip: bad total length " + total);
        if (total > b.length)
            throw new Bad("ip: truncated (total length " + total + ", available " + b.length + ")");
        int flags = word(b, 6);
        p.put("ip.hdr_len", h);
        p.put("ip.tos", b[1]);
        p.put("ip.len", total);
        p.put("ip.id", word(b, 4));
        p.put("ip.flags.df", (flags >> 14) & 1);
        p.put("ip.flags.mf", (flags >> 13) & 1);
        p.put("ip.frag_offset", flags % 8192 * 8);
        p.put("ip.ttl", b[8]);
        p.put("ip.proto", b[9]);
        p.put("ip.checksum", word(b, 10));
        p.put("ip.checksum.status", checksum(slice(b, 0, h)));
        p.put("ip.src", integer(b, 12, 4));
        p.put("ip.dst", integer(b, 16, 4));
        if ((flags & 8192) != 0 || flags % 8192 != 0)
            p.put("ip.fragment", 0);
        return slice(b, h, total);
    }
}

import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.io.IOException;
import java.util.*;
import java.util.function.Predicate;
public final class Main {
    static final class Packet {
        int number, length;
        long time;
        int[] bytes = new int[0], data = new int[0];
        String reason, duplicate = "";
        List<String> layers = new ArrayList<>(), answers = new ArrayList<>();
        Map<String, List<Object>> fields = new HashMap<>();
        Packet(int number, long time, int length) {
            this.number = number;
            this.time = time;
            this.length = length;
        }
        void put(String name, long value) {
            fields.put(name, new ArrayList<>(List.of(value)));
        }
        void put(String name, String value) {
            fields.put(name, new ArrayList<>(List.of(value)));
        }
        void append(String name, long value) {
            fields.computeIfAbsent(name, key -> new ArrayList<>()).add(value);
        }
        void append(String name, String value) {
            fields.computeIfAbsent(name, key -> new ArrayList<>()).add(value);
        }
        boolean has(String name) {
            return fields.containsKey(name);
        }
        long num(String name) {
            return (Long)fields.get(name).getFirst();
        }
        String text(String name) {
            return (String)fields.get(name).getFirst();
        }
        List<Object> values(String name) {
            return fields.getOrDefault(name, List.of());
        }
    }
    static final String[][] FIELDS = {{"frame.number", "integer"},
